module.exports = {
    onConnect: function(transport, config) {
        engine.setStatus('connecting', 'Connecting to ProPresenter 7...');
    },

    onTransportReady: function(transport, config) {
        engine.setStatus('connected', 'Ready');
        engine.setVariable('active_presentation', 'Sunday Morning Service');
        engine.setVariable('current_slide_index', '1');
        engine.setVariable('total_slides', '12');
    },

    onAction: function(transport, actionId, params) {
        engine.setVariable('last_action', actionId);

        if (actionId === 'next_slide') {
            var current = parseInt(engine.getVariable('current_slide_index'), 10) || 1;
            var total = parseInt(engine.getVariable('total_slides'), 10) || 12;
            var next = Math.min(total, current + 1);
            engine.setVariable('current_slide_index', String(next));
            return 'Advanced to slide ' + next + ' of ' + total;
        }

        if (actionId === 'prev_slide') {
            var current = parseInt(engine.getVariable('current_slide_index'), 10) || 1;
            var prev = Math.max(1, current - 1);
            engine.setVariable('current_slide_index', String(prev));
            return 'Returned to slide ' + prev;
        }

        if (actionId === 'clear_all') {
            engine.setVariable('current_slide_index', '0');
            return 'Cleared all layers';
        }

        if (actionId === 'clear_slide') {
            return 'Cleared text slide layer';
        }

        if (actionId === 'trigger_slide') {
            var target = params.slide_index || '1';
            engine.setVariable('current_slide_index', String(target));
            return 'Triggered slide #' + target;
        }

        if (actionId === 'trigger_macro') {
            var macro = params.macro_name || 'Default';
            return 'Dispatched macro: ' + macro;
        }

        return 'Executed action ' + actionId;
    },

    onMessage: function(transport, text, bytes) {
        try {
            var data = JSON.parse(text);
            if (data.presentation && data.presentation.name) {
                engine.setVariable('active_presentation', data.presentation.name);
            }
            if (data.slide_index !== undefined) {
                engine.setVariable('current_slide_index', String(data.slide_index));
            }
        } catch(e) {}
    }
};
